'use strict';
let receiptPurchaseId='';
const localDay=()=>new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);
const ownDoc=id=>[...state.orders,...state.purchases,...(state.finance?.manual_documents||[])].find(d=>d.id===id);
const docLabel=id=>ownDoc(id)?.data.reference||ownDoc(id)?.data.external_id||ownDoc(id)?.data.supplier||id;
const financeKind=k=>({payable:'A pagar',receivable:'A receber',refund:'Reembolso',commission:'Comissão'})[k]||k;
const payableAmount=i=>i?.kind==='commission'?Math.min(Number(i.remaining),Number(i.released_remaining||0)).toFixed(2):i?.remaining||'0';
const moneyField=(name,label,value='0')=>`<label>${label}<input name="${name}" type="number" min="0" step="0.01" value="${esc(value)}" required></label>`;

let purchaseEditing='',purchaseFrom='',purchaseTo='',purchaseStatus='',purchaseSelection=new Set(),purchaseOffset=0;
// Bling's names for the purchase situations: received with stock and accounts is "Atendido".
const purchaseStateNames={open:'Em aberto',partial:'Em andamento',received:'Atendido',cancelled:'Cancelado'};
const purchaseBadge=status=>`<span class="badge ${status==='received'?'good':['open','partial'].includes(status)?'warn':'dim'}">${esc(purchaseStateNames[status]||status)}</span>`;
const purchaseMatches=()=>state.purchases.filter(p=>{
 const d=p.data,query=(p.id+' '+(d.number||'')+' '+(d.purchase_order||'')+' '+d.supplier+' '+d.items.map(i=>i.sku).join(' ')).toLowerCase();
 return query.includes(purchaseQuery.toLowerCase())&&(!purchaseStatus||p.status===purchaseStatus)&&(!purchaseFrom||d.date&&d.date>=purchaseFrom)&&(!purchaseTo||d.date&&d.date<=purchaseTo);
});
const canEditPurchase=p=>!p||!p.data.stock_posted&&!p.data.accounts_posted&&!(state.procurement?.receipts||[]).some(r=>r.document_id===p.id&&r.status==='received')&&!state.accounts.some(a=>a.document_id===p.id&&a.kind==='payable'&&a.status!=='cancelled');
function purchasePlanLine(i={due_date:localDay(),amount:''}){return `<div class="forms" data-purchase-installment><label>Vencimento<input name="purchase_due_date" type="date" value="${esc(i.due_date)}" required></label>${moneyField('purchase_amount','Valor da parcela (R$)',i.amount)}<button type="button" class="action" data-remove-purchase-installment>Remover parcela</button></div>`;}
function purchaseDocumentForm(){
 const p=state.purchases.find(p=>p.id===purchaseEditing),d=p?.data||{},editable=canEditPurchase(p)&&p?.status!=='cancelled';
 const contact=d.contact?.id||'',method=d.payment_method?.id||'';
 const contacts=(state.contacts||[]).filter(c=>c.data.status==='active'&&c.data.roles.includes('supplier')||c.id===contact);
 const methods=(state.payment_methods||[]).filter(m=>m.data.status==='active'&&['payable','both'].includes(m.data.applicability)||m.id===method);
 const history=(state.procurement?.history||[]).filter(h=>h.purchase_id===p?.id);
 return panel('Pedido de compra','Salvar a compra, receber mercadoria e lançar contas são ações separadas.',`<form id="purchase-form"><input type="hidden" name="id" value="${esc(p?.id||'')}"><input type="hidden" name="version" value="${d.version||0}"><div class="form-footer"><button type="button" class="secondary" id="purchase-form-cancel">Cancelar</button><button ${editable?'':'disabled'}>Salvar compra</button></div>${p&&!editable?'<p class="origin-note">'+(p.status==='cancelled'?'Compra cancelada. Reabra para editar.':'Estorne os recebimentos e as contas antes de editar os dados da compra.')+'</p>':''}<fieldset class="sale-fields" ${editable?'':'disabled'}><h3>Fornecedor</h3><div class="forms"><label>Cadastro do fornecedor<select name="contact_id"><option value="">Informar somente o nome</option>${contacts.map(c=>`<option value="${esc(c.id)}" ${c.id===contact?'selected':''}>${esc(c.data.name)} · ${c.code}</option>`).join('')}${contact&&!contacts.some(c=>c.id===contact)?`<option value="${esc(contact)}" selected>${esc(d.contact.name)} · cadastro preservado</option>`:''}</select></label><label>Fornecedor<input name="supplier" value="${esc(d.supplier||'')}" required maxlength="120"></label>${depotField('depot','Depósito de recebimento',d.depot||null,true)}</div>${contact?'<label class="checkline"><input type="checkbox" name="refresh_contact">Atualizar os dados do fornecedor pela versão atual do cadastro</label>':''}<h3>Itens do pedido de compra</h3>${itemsForm(false,true,d.items)}${purchaseSupplierItems(d)}${p?'<label class="checkline"><input type="checkbox" name="refresh_supplier_items">Atualizar códigos e condições dos itens pela versão atual do fornecedor</label>':''}<h3>Totais da compra</h3><div class="forms">${moneyField('freight','Frete (R$)',d.freight||'0')}${moneyField('discount','Desconto (R$)',d.discount||'0')}${moneyField('charges','Encargos informados (R$)',d.charges||'0')}</div><p class="sale-total">Total do pedido <output id="purchase-total">${brl(d.total||0)}</output></p><p class="source-line">Frete, desconto e encargos são rateados entre os itens. Tributos não são calculados automaticamente.</p><h3>Detalhes da compra</h3><div class="forms"><label>Número do pedido<input name="number" value="${esc(d.number||'')}" maxlength="120" placeholder="Gerado ao salvar"></label><label>Ordem de compra<input name="purchase_order" value="${esc(d.purchase_order||'')}" maxlength="120"></label><label>Data da compra<input name="date" type="date" value="${esc(d.date||localDay())}" required></label><label>Data prevista<input name="expected_date" type="date" value="${esc(d.expected_date||'')}"></label></div><h3>Pagamento</h3><label>Forma de pagamento<select name="payment_method_id"><option value="">Informar parcelas manualmente</option>${methods.map(m=>`<option value="${esc(m.id)}" ${m.id===method?'selected':''}>${esc(m.name)}</option>`).join('')}${method&&!methods.some(m=>m.id===method)?`<option value="${esc(method)}" selected>${esc(d.payment_method.name)} · condição preservada</option>`:''}</select></label>${method?'<label class="checkline"><input type="checkbox" name="refresh_payment_method">Recalcular usando a versão atual da forma de pagamento</label>':''}<div id="purchase-manual-plan" ${method?'hidden':''}><div class="forms"><label>Condição em dias<input name="terms_days" placeholder="Ex.: 30, 60, 90" maxlength="600"></label><button type="button" class="action" id="purchase-generate-plan">Gerar parcelas</button></div><div id="purchase-plan-lines">${!method?(d.installments||[]).map(purchasePlanLine).join(''):''}</div><button type="button" class="add-item" id="purchase-add-installment">Adicionar parcela</button><p class="source-line">Sem parcelas informadas, o total vence na data da compra. A forma cadastrada preserva prazos e calendário próprios.</p></div>${d.installments?.length?`<details><summary>Condição registrada nesta versão</summary>${table(['Vencimento','Valor'],d.installments.map(i=>`<tr><td>${purchaseDate(i.due_date)}</td><td>${brl(i.amount)}</td></tr>`).join(''))}</details>`:''}<h3>Transportador</h3><div class="forms"><label>Nome<input name="carrier_name" value="${esc(d.carrier_name||'')}" maxlength="120"></label><label>Frete por conta<select name="freight_payer">${[['unspecified','Selecione uma opção'],['supplier','Fornecedor'],['recipient','Destinatário'],['third_party','Terceiros'],['none','Sem frete']].map(([v,n])=>`<option value="${v}" ${v===(d.freight_payer||'unspecified')?'selected':''}>${n}</option>`).join('')}</select></label><label>Quantidade de volumes<input name="packages" type="number" min="0" step="1" value="${Number(d.packages||0)}"></label><label>Peso bruto (kg)<input name="gross_weight" type="number" min="0" step="0.001" value="${esc(d.gross_weight||'0')}"></label></div><h3>Dados adicionais</h3><label>Observações<textarea name="notes" maxlength="2000" rows="3">${esc(d.notes||'')}</textarea></label><label>Observações internas<textarea name="internal_notes" maxlength="2000" rows="3">${esc(d.internal_notes||'')}</textarea></label></fieldset>${p?`<label>Motivo da alteração<input name="reason" maxlength="120" ${editable?'required':''}></label><div class="form-footer"><span>Versão ${d.version||0}. Salvar não recebe mercadoria nem gera contas.</span>${canEditPurchase(p)?`<button type="button" class="secondary" data-purchase-state="${p.status==='cancelled'?'reopen':'cancel'}">${p.status==='cancelled'?'Reabrir compra':'Cancelar compra'}</button>`:''}<button ${editable?'':'disabled'}>Salvar compra</button></div>`:'<div class="form-footer"><span>Conferência e lançamentos continuam nas ações da compra.</span><button>Salvar compra</button></div>'}</form>${history.length?`<details><summary>Histórico da compra (${history.length} versões)</summary>${table(['Versão','Quando','Motivo','Fornecedor / total'],history.map(h=>`<tr><td>${h.version}</td><td>${when(h.created_at)}</td><td>${esc(h.reason)}</td><td>${esc(h.data.supplier)}<small>${brl(h.data.total)}</small></td></tr>`).join(''))}</details>`:''}`);
}
function submitPurchaseForm(form){
 const p=Object.fromEntries(new FormData(form)),payload={};
 for(const k of ['supplier','depot','freight','discount','charges','contact_id','payment_method_id','number','purchase_order','date','expected_date','carrier_name','freight_payer','packages','gross_weight','notes','internal_notes'])payload[k]=p[k]||'';
 payload.items=formItems(form);payload.refresh_contact=p.refresh_contact==='on';payload.refresh_payment_method=p.refresh_payment_method==='on';payload.refresh_supplier_items=p.refresh_supplier_items==='on';
 const installments=[...form.querySelectorAll('[data-purchase-installment]')].map(r=>({due_date:r.querySelector('[name=purchase_due_date]').value,amount:r.querySelector('[name=purchase_amount]').value}));
 if(!p.payment_method_id&&installments.length)payload.installments=installments;
 if(p.id){payload.id=p.id;payload.version=Number(p.version);payload.reason=p.reason;}
 command(p.id?'purchase.update':'purchase.create',payload);
}
function purchaseSupplierItems(data){
 const rows=Object.values(data.supplier_items||{});if(!rows.length)return '';
 return `<details><summary>Referências do fornecedor preservadas (${rows.length})</summary>${table(['Produto','Código no fornecedor','Descrição no fornecedor','Preço de compra cadastrado','Custo cadastrado','Garantia'],rows.map(r=>`<tr><td>${esc(r.sku)}<small>Versão ${r.supplier_version}</small></td><td>${esc(r.code)}</td><td>${esc(r.description)}</td><td>${r.purchase_price===null?'—':brl(r.purchase_price)}</td><td>${r.cost_price===null?'—':brl(r.cost_price)}</td><td>${r.warranty_months} meses</td></tr>`).join(''))}<p class="source-line">São as referências usadas na compra. O preço efetivo e o custo rateado desta compra permanecem nos seus itens e recebimentos.</p></details>`;
}
const purchaseDate=value=>value?String(value).split('-').reverse().join('/'):'Não informada';
function purchaseToolbar(){
 const filters=[purchaseQuery&&'Pesquisa: '+esc(purchaseQuery),purchaseStatus&&'Situação: '+esc(purchaseStateNames[purchaseStatus]||purchaseStatus),(purchaseFrom||purchaseTo)&&'Data da compra: '+purchaseDate(purchaseFrom)+' até '+purchaseDate(purchaseTo)].filter(Boolean).join(' · ');
 return `<form id="purchase-query" class="sales-search-form"><div class="sales-toolbar"><button type="button" class="icon-button" data-purchase-filter-toggle aria-label="Filtros adicionais">${icon('filter')}</button><div class="sales-search"><input name="query" value="${esc(purchaseQuery)}" placeholder="Pesquisa por nome, número do pedido ou ordem de compra" aria-label="Pesquisa por nome, número do pedido ou ordem de compra"><button aria-label="Pesquisar">${icon('search')}</button></div><button type="button" class="action" data-purchase-filter-toggle aria-label="Filtro de período">${icon('calendar')}${purchaseFrom||purchaseTo?' '+purchaseDate(purchaseFrom)+' até '+purchaseDate(purchaseTo):' Data da compra'}</button></div><div class="filter-caption">${filters||'Nenhum filtro aplicado'}${filters?' <button type="button" class="action" id="purchase-clear-filters">Limpar</button>':''}</div></form>`;
}
function procurementPage(){
 const receipts=state.procurement?.receipts||[],purchaseRows=purchaseMatches();
 const offset=Math.min(purchaseOffset,Math.max(0,Math.floor((purchaseRows.length-1)/50)*50)),visible=purchaseRows.slice(offset,offset+50);
 const purchase=state.purchases.find(p=>p.id===receiptPurchaseId&&p.status!=='cancelled')||state.purchases.find(p=>p.status!=='cancelled');
 const received=purchase?.data.received||purchase?.data.items.map(i=>purchase.data.stock_posted?i.quantity:'0')||[];
 const chooser=`<label>Compra<select id="receipt-purchase" name="id">${state.purchases.filter(p=>p.status!=='cancelled').map(p=>`<option value="${esc(p.id)}" ${p.id===purchase?.id?'selected':''}>${esc(p.data.number||p.id.slice(0,8))} · ${esc(p.data.supplier)} · ${brl(p.data.total)}</option>`).join('')}</select></label>`;
 const rows=purchase?.data.items.map((i,index)=>`<div class="receipt-line" data-receipt-line="${index}"><div><strong>${esc(i.sku)}</strong><small>Comprado: ${qty(i.quantity)} · recebido: ${qty(received[index])}</small></div><label>Quantidade recebida<input name="received_quantity" type="number" min="0" max="${Number(i.quantity)-Number(received[index])}" step="0.001" value="0"></label><label>Lote / identificação<input name="lot" maxlength="120" placeholder="Opcional"></label></div>`).join('')||'';
 return panel('Pedidos de compra','',purchaseToolbar()+`<details id="purchase-filter-options"><summary>Filtros de período e situação</summary><form id="purchase-filters"><div class="forms"><label>Data inicial<input name="from" type="date" value="${esc(purchaseFrom)}"></label><label>Data final<input name="to" type="date" value="${esc(purchaseTo)}"></label><label>Situação<select name="status"><option value="">Todas as situações</option>${Object.entries(purchaseStateNames).map(([v,n])=>`<option value="${v}" ${v===purchaseStatus?'selected':''}>${n}</option>`).join('')}</select></label><button>Aplicar filtros</button></div></form></details>`+table([`<input type="checkbox" id="purchase-all" aria-label="Selecionar compras desta página" ${visible.length&&visible.every(p=>purchaseSelection.has(p.id))?'checked':''}>`,'Número','Data','Fornecedor','Observação interna','Total (R$)','Situação','Vinculações','Ações'],visible.map(p=>{const d=p.data,linked=(state.inbound?.invoices||[]).filter(n=>n.purchase_id===p.id);return `<tr><td><input type="checkbox" data-purchase-select="${esc(p.id)}" aria-label="Selecionar compra ${esc(d.number||p.id)}" ${purchaseSelection.has(p.id)?'checked':''}></td><td><button class="action" data-edit-purchase="${esc(p.id)}">${esc(d.number||p.id.slice(0,8))}</button>${d.purchase_order?`<small>OC ${esc(d.purchase_order)}</small>`:''}</td><td>${purchaseDate(d.date)}${d.expected_date?`<small>Prevista: ${purchaseDate(d.expected_date)}</small>`:''}</td><td>${esc(d.supplier)}</td><td class="purchase-note">${esc((d.internal_notes||'').slice(0,80))||'<span class="dim">—</span>'}</td><td class="num">${brl(d.total).replace('R$','').trim()}</td><td>${purchaseBadge(p.status)}<small>Contas ${d.accounts_posted?'lançadas':'não lançadas'}</small></td><td>${linked.length?`<span class="badge good">Vinculado</span><small>${linked.map(n=>'NF-e '+esc(String(n.number||n.key||'').slice(-9))).join(', ')}</small>`:'<span class="badge dim">Não vinculado</span>'}</td><td><details><summary aria-label="Ações da compra ${esc(d.number||p.id)}">${icon('more')}</summary><div class="action-group"><button class="action" data-edit-purchase="${esc(p.id)}">Abrir compra</button>${p.status==='cancelled'?'':(!d.stock_posted?`<button class="action" data-receive-purchase="${esc(p.id)}">Recebimento parcial</button>`+button('Receber saldo restante','purchase.stock',p.id):'')+button('Estornar recebimentos','purchase.reverse_stock',p.id)+button(d.accounts_posted?'Estornar conta':'Lançar contas',d.accounts_posted?'purchase.reverse_accounts':'purchase.accounts',p.id)}<a class="action" href="/api/erp-local/purchases/print?ids=${encodeURIComponent(p.id)}" target="_blank" rel="noopener">Imprimir compra</a></div></details></td></tr>`;}).join('')||empty(7,'Nenhum resultado encontrado.'))+`<div class="table-footer"><span>${purchaseRows.length?offset+1:0}–${Math.min(offset+50,purchaseRows.length)} de ${purchaseRows.length} compras · ${purchaseSelection.size} selecionadas</span><div><button type="button" class="action" data-purchase-page="-1" ${offset===0?'disabled':''}>Anterior</button><button type="button" class="action" data-purchase-page="1" ${offset+50>=purchaseRows.length?'disabled':''}>Próxima</button></div></div>`)+purchaseDocumentForm()+
 panel('Recebimento parcial','Informe somente o que chegou. O identificador impede lançar o mesmo recebimento duas vezes.',purchase?`<form id="receipt-form"><div class="forms">${chooser}<label>Identificador do recebimento<input name="receipt_id" value="REC-${crypto.randomUUID()}" required maxlength="120"></label></div><div class="line-items">${rows}</div><div class="form-footer"><span>O recebimento não gera a conta automaticamente.</span><button>Registrar recebimento local</button></div></form>`:'<p class="muted">Cadastre uma compra em aberto para receber os itens.</p>')+
 '<details class="purchase-receipt-history"><summary>Recebimentos registrados ('+receipts.length+')</summary>'+panel('Recebimentos registrados','Estornos preservam o recebimento original e exigem saldo livre para retirar as peças.',table(['Quando / fornecedor','Itens / custo unitário','Situação','Ação'],receipts.map(r=>`<tr><td>${when(r.data.created_at)}<small>${esc(docLabel(r.document_id))}</small></td><td>${r.data.lines.map(i=>`${qty(i.quantity)} × ${esc(i.sku)} · ${brl(i.unit_cost)}${i.lot?' · lote '+esc(i.lot):''}`).join('<br>')}</td><td>${r.status==='received'?'Recebido':'Estornado'}</td><td>${r.status==='received'?button('Estornar recebimento','purchase.reverse_receipt',r.id):'—'}</td></tr>`).join('')||empty(4,'Nenhum recebimento registrado.')))+'</details>';
}
document.addEventListener('click',e=>{
 const pg=e.target.closest('[data-purchase-page]'),batch=e.target.closest('[data-purchase-batch]');
 if(pg){purchaseOffset=Math.max(0,purchaseOffset+Number(pg.dataset.purchasePage)*50);render();}
 if(batch&&purchaseSelection.size)command('purchases.batch',{ids:[...purchaseSelection],action:batch.dataset.purchaseBatch});
 if(e.target.closest('[data-purchase-filter-toggle]')){const f=document.getElementById('purchase-filter-options');f.open=!f.open;}
 if(e.target.closest('#purchase-clear-filters')){purchaseQuery='';purchaseFrom='';purchaseTo='';purchaseStatus='';purchaseOffset=0;purchaseSelection.clear();render();}
 const edit=e.target.closest('[data-edit-purchase]'),receive=e.target.closest('[data-receive-purchase]');
 if(receive){receiptPurchaseId=receive.dataset.receivePurchase;purchaseEditing='';render();const f=document.getElementById('receipt-form');f.closest('.panel').classList.add('form-open');f.scrollIntoView({behavior:'smooth'});}
 if(edit){purchaseEditing=edit.dataset.editPurchase;render();const f=document.getElementById('purchase-form');f.closest('.panel').classList.add('form-open');f.scrollIntoView({behavior:'smooth'});updateDocumentTotal(f,document.getElementById('purchase-total'));}
 if(e.target.closest('#purchase-form-cancel')){purchaseEditing='';render();}
 if(e.target.closest('[data-purchase-state]')){const f=e.target.closest('form'),p=Object.fromEntries(new FormData(f));if(!p.reason?.trim()){message('Informe o motivo da alteração.',true);return;}command('purchase.'+e.target.closest('[data-purchase-state]').dataset.purchaseState,{id:p.id,version:Number(p.version),reason:p.reason});}
 if(e.target.closest('#purchase-print')){if(purchaseSelection.size)window.open('/api/erp-local/purchases/print?ids='+encodeURIComponent([...purchaseSelection].join(',')),'_blank','noopener');}
 if(e.target.closest('#purchase-add-installment'))document.getElementById('purchase-plan-lines').insertAdjacentHTML('beforeend',purchasePlanLine());
 if(e.target.closest('[data-remove-purchase-installment]'))e.target.closest('[data-purchase-installment]').remove();
 if(e.target.closest('#purchase-generate-plan')){
  const f=e.target.closest('form'),value=f.querySelector('[name=terms_days]').value.trim(),date=f.querySelector('[name=date]').value;
  try{
   if(!/^\d+(\s*,\s*\d+)*$/.test(value))throw Error('Informe os prazos separados por vírgula.');
   const days=value.split(',').map(v=>Number(v.trim()));if(days.length>120||days.some((d,i)=>d>3650||i&&d<=days[i-1])||!date)throw Error('Informe prazos únicos e crescentes, até 3650 dias, e a data da compra.');
   const fixed=(v,p)=>{if(!/^\d+(\.\d*)?$/.test(v))throw Error('Confira os valores.');const [a,b='']=v.split('.');if(b.length>p)throw Error('Confira a precisão dos valores.');return BigInt(a)*10n**BigInt(p)+BigInt(b.padEnd(p,'0'));};
   let sum=0n;for(const r of f.querySelectorAll('.item-line'))sum+=fixed(r.querySelector('[name=quantity]').value,3)*fixed(r.querySelector('[name=unit_price]').value,4);
   let cents=(sum+50000n)/100000n;for(const n of ['freight','discount','charges'])cents+=(n==='discount'?-1n:1n)*fixed(f.querySelector(`[name=${n}]`).value||'0',2);
   const count=BigInt(days.length);if(cents<count)throw Error('Cada parcela precisa ter ao menos um centavo.');
   const plan=days.map((d,i)=>{const dt=new Date(date+'T00:00:00Z');dt.setUTCDate(dt.getUTCDate()+d);const v=cents/count+(BigInt(i)<cents%count?1n:0n);return {due_date:dt.toISOString().slice(0,10),amount:(v/100n)+'.'+String(v%100n).padStart(2,'0')};});
   document.getElementById('purchase-plan-lines').innerHTML=plan.map(purchasePlanLine).join('');
  }catch(error){message(error.message,true);}
 }
});
document.addEventListener('change',e=>{
 const f=e.target.closest('#purchase-form');
 if(e.target.id==='purchase-all'){for(const p of purchaseMatches().slice(purchaseOffset,purchaseOffset+50))e.target.checked?purchaseSelection.add(p.id):purchaseSelection.delete(p.id);render();}
 if(e.target.matches('[data-purchase-select]')){e.target.checked?purchaseSelection.add(e.target.dataset.purchaseSelect):purchaseSelection.delete(e.target.dataset.purchaseSelect);render();}
 if(f){if(e.target.name==='contact_id'){const c=(state.contacts||[]).find(c=>c.id===e.target.value);if(c)f.querySelector('[name=supplier]').value=c.data.name;}if(e.target.name==='payment_method_id')f.querySelector('#purchase-manual-plan').hidden=!!e.target.value;updateDocumentTotal(f,document.getElementById('purchase-total'));}
});
document.addEventListener('input',e=>{const f=e.target.closest('#purchase-form');if(f)updateDocumentTotal(f,document.getElementById('purchase-total'));});
document.addEventListener('submit',e=>{if(e.target.id==='purchase-filters'){e.preventDefault();const p=Object.fromEntries(new FormData(e.target));if(p.from&&p.to&&p.from>p.to){message('Confira o período da compra.',true);return;}purchaseFrom=p.from;purchaseTo=p.to;purchaseStatus=p.status;purchaseOffset=0;purchaseSelection.clear();render();}});

// Bling's "Gerenciar categorias": income and expense, with subcategories.
function financeCategoriesPanel(){
  const list=state.finance_categories?.categories||[];
  const rows=list.map(c=>`<tr><td>${esc(c.path)}</td><td>${c.kind==='income'?'Receita':'Despesa'}</td><td>${c.active?'<span class="badge good">Ativa</span>':'<span class="badge dim">Inativa</span>'}</td><td><button type="button" class="action" data-category-toggle="${esc(c.id)}">${c.active?'Desativar':'Ativar'}</button></td></tr>`).join('');
  return panel('Categorias financeiras','Use em contas a pagar (despesa) e a receber (receita). Categoria não é apagada: desative para não usar mais.',`<form id="finance-category-form"><div class="forms"><label>Nome<input name="name" required maxlength="80"></label><label>Tipo<select name="kind"><option value="expense">Despesa</option><option value="income">Receita</option></select></label><label>Dentro de<select name="parent_id"><option value="">Nenhuma (principal)</option>${list.filter(c=>c.active).map(c=>`<option value="${esc(c.id)}">${c.kind==='income'?'Receita':'Despesa'} · ${esc(c.path)}</option>`).join('')}</select></label></div><div class="form-footer"><span>Subcategorias ficam no mesmo tipo da categoria de cima.</span><button>Salvar categoria</button></div></form>`+table(['Categoria','Tipo','Situação',''],rows||empty(4,'Nenhuma categoria cadastrada.')));
}
// Bling's "Importação de registros financeiros": check the file first, then import.
let financeImport=null;
function financeImportPanel(){
  const v=financeImport,rows=(v?.result?.lines||[]).map(r=>`<tr><td>${r.line}</td><td>${r.payload?esc(r.payload.kind==='receivable'?'Receber':'Pagar'):'—'}</td><td>${esc(r.payload?.party||'—')}</td><td>${r.payload?esc(r.payload.due_date.split('-').reverse().join('/')):'—'}</td><td class="num">${r.payload?brl(r.payload.amount).replace(/^R\$\s*/,''):'—'}</td><td>${r.ok?(r.duplicate?'<span class="badge dim">Já importada</span>':'<span class="badge good">Pronta</span>'):`<span class="badge late">Recusada</span><small>${esc(r.error||'')}</small>`}</td></tr>`).join('');
  return panel('Importar contas por planilha','Envie um CSV com as colunas Tipo, Cliente/Fornecedor, Valor, Vencimento e, se quiser, Emissão, Competência, Histórico, Forma de pagamento, Categoria, Nº documento e Conta financeira. Primeiro o ERP confere tudo sem gravar; depois você importa. Reenviar o mesmo arquivo não duplica.',`<form id="finance-import-form"><div class="forms"><label>Tipo quando a planilha não informa<select name="kind"><option value="payable">Conta a pagar</option><option value="receivable">Conta a receber</option></select></label><label>Arquivo CSV<input type="file" name="sheet" accept=".csv,.txt,text/csv" required></label></div><div class="form-footer"><span>Nada é gravado na conferência.</span><button>Conferir planilha</button></div></form>`+(v?`<p class="source-line">${v.result.valid} linha(s) prontas e ${v.result.refused} recusada(s).</p>`+table(['Linha','Tipo','Cliente / Fornecedor','Vencimento','Valor','Situação'],rows)+`<div class="form-footer"><button type="button" class="secondary" id="finance-import-cancel">Descartar</button><button type="button" id="finance-import-commit" ${v.result.valid?'':'disabled'}>Importar ${v.result.valid} conta(s)</button></div>`:''));
}
document.addEventListener('submit',async e=>{
  if(e.target.getAttribute('id')!=='finance-import-form')return;
  e.preventDefault();const f=new FormData(e.target),text=await f.get('sheet').text(),kind=f.get('kind');
  const response=await fetch('/api/erp-local/finance/import?kind='+encodeURIComponent(kind),{method:'POST',headers:{'X-ERP-Local':'1','Content-Type':'text/plain'},body:text});
  const reply=await response.json();
  if(!response.ok){message(reply.message||'Planilha não aceita.',true);return;}
  financeImport={text,kind,result:reply};render();
  document.getElementById('finance-import-form')?.closest('.panel')?.classList.add('form-open');
});
document.addEventListener('click',async e=>{
  if(e.target.closest('#finance-import-cancel')){financeImport=null;render();return;}
  if(!e.target.closest('#finance-import-commit')||!financeImport)return;
  const response=await fetch('/api/erp-local/finance/import?commit=1&kind='+encodeURIComponent(financeImport.kind),{method:'POST',headers:{'X-ERP-Local':'1','Content-Type':'text/plain'},body:financeImport.text});
  const reply=await response.json();
  if(!response.ok){message(reply.message||'Importação não concluída.',true);return;}
  financeImport=null;await refresh();message(`${reply.imported} conta(s) importada(s)${reply.refused.length?`; ${reply.refused.length} recusada(s)`:''}.`);
});
function financeCategoryOf(accountId){
  const v=state.finance_categories||{},id=(v.assignments||{})[accountId];
  return id?(v.categories||[]).find(c=>c.id===id)?.path||'':'';
}
document.addEventListener('submit',e=>{
  if(e.target.getAttribute('id')!=='finance-category-form')return;
  e.preventDefault();const f=Object.fromEntries(new FormData(e.target));
  command('finance.category.save',{name:f.name,kind:f.kind,...(f.parent_id?{parent_id:f.parent_id}:{})});
});
document.addEventListener('click',e=>{
  const toggle=e.target.closest('[data-category-toggle]');
  if(toggle){const c=(state.finance_categories?.categories||[]).find(c=>c.id===toggle.dataset.categoryToggle);if(c)command('finance.category.save',{id:c.id,version:c.version,name:c.name,kind:c.kind,...(c.parent_id?{parent_id:c.parent_id}:{}),active:!c.active});}
  if(e.target.closest('#finance-category-toggle')){const m=document.getElementById('finance-category-menu');if(m)m.hidden=!m.hidden;}
  if(e.target.closest('#finance-category-apply')&&financeSelection.size){
    const ids=[...new Set([...financeSelection].map(i=>(state.finance?.installments||[]).find(x=>x.id===i)?.account_id).filter(Boolean))];
    command('finance.category.assign',{account_ids:ids,category_id:document.getElementById('finance-category-choice').value});financeSelection.clear();
  }
});
function financePage(){
  const f=state.finance||{banks:[],installments:[],payments:[],matches:[]};
  const pending=f.installments.filter(i=>i.account_status!=='cancelled'&&Number(i.remaining)>0&&(i.kind!=='commission'||Number(i.released_remaining)>0));
  const eligible=state.accounts.filter(a=>a.status==='open'&&Number(a.amount)>0);
  const first=pending[0];
  const unpaired=f.payments.filter(p=>p.bank_id&&!p.reversed&&!f.matches.some(m=>m.payment_id===p.id));
  return panel('Contas e parcelas','Tudo nesta tela registra fatos no banco local. Nenhuma transferência ou cobrança é enviada ao banco.',financeLedgerTable(f))+
  manualFinancePanel()+financeCategoriesPanel()+financeImportPanel()+
  panel('Plano de parcelas','A soma das parcelas precisa ser exatamente o valor da conta. Contas com baixas precisam de conciliação antes de trocar o plano.',eligible.length?`<form id="schedule-form"><label>Conta<select name="id">${eligible.map(a=>`<option value="${esc(a.id)}">${esc(docLabel(a.document_id))} · ${financeKind(a.kind)} · ${brl(a.amount)}</option>`).join('')}</select></label><div id="schedule-lines">${scheduleLine(eligible[0].amount)}</div><div class="form-footer"><button type="button" class="secondary" id="add-schedule-line">Adicionar parcela</button><button>Definir parcelas localmente</button></div></form>`:'<p class="muted">Sem contas abertas para definir um plano.</p>')+
  panel('Registrar baixa','Principal, taxas, desconto, juros e valor líquido são registrados separadamente. A baixa não efetua pagamento real.',pending.length?`<form id="payment-form"><div class="forms"><label>Parcela<select name="installment_id" id="payment-installment">${pending.map(i=>`<option value="${esc(i.id)}">${esc(docLabel(state.accounts.find(a=>a.id===i.account_id)?.document_id))} · ${esc(i.due_date)} · saldo ${brl(i.remaining)}</option>`).join('')}</select></label>${moneyField('amount','Principal (R$)',payableAmount(first))}${moneyField('fee','Taxa (R$)')}${moneyField('discount','Desconto (R$)')}${moneyField('interest','Juros (R$)')}<label>Conta financeira<select name="bank_id"><option value="">Sem lançamento em caixa</option>${options(f.banks)}</select></label><label>Data<input name="date" type="date" value="${localDay()}" required></label><label>Comprovante / identificador<input name="external_id" value="PG-${crypto.randomUUID()}" required maxlength="120"></label></div><div class="form-footer"><span>Não efetua pagamento real.</span><button>Registrar baixa local</button></div></form>`:'<p class="muted">Sem parcelas pendentes.</p>')+
  panel('Contas financeiras locais','O saldo parte da abertura informada e dos valores líquidos das baixas. São registros de teste, sem conexão bancária.',`<form id="bank-form"><div class="forms"><label>Código<input name="id" required maxlength="120" placeholder="caixa-teste"></label><label>Nome<input name="name" required maxlength="120" placeholder="Caixa de teste"></label>${moneyField('opening','Abertura (R$)')}</div><div class="form-footer"><span>Não abre conta em instituição financeira.</span><button>Cadastrar conta local</button></div></form>`+table(['Conta','Abertura','Saldo calculado'],f.banks.map(b=>`<tr><td>${esc(b.name)}</td><td>${brl(b.opening)}</td><td>${brl(b.balance)}</td></tr>`).join('')||empty(3,'Nenhuma conta financeira local.')))+
  statementPanel(f)+
  panel('Conciliação de extrato','A associação exige o valor líquido exato com sinal: entrada positiva, saída negativa.',unpaired.length?`<form id="reconcile-form"><div class="forms"><label>Baixa<select name="id">${unpaired.map(p=>`<option value="${esc(p.id)}">${esc(p.id.slice(0,8))} · caixa ${brl(p.cash)}</option>`).join('')}</select></label><label>Identificador da linha do extrato<input name="statement_line" required maxlength="120"></label><label>Valor com sinal (R$)<input name="amount" type="number" step="0.01" required></label></div><div class="form-footer"><span>Conferência manual de uma linha; não consulta o banco.</span><button>Conciliar localmente</button></div></form>`:'<p class="muted">Sem baixas em conta financeira para conciliar.</p>')+
  panel('Baixas e estornos','Desfazer conciliação libera o estorno. O histórico da baixa é preservado.',table(['Quando / identificador','Principal','Caixa líquido','Situação / ação'],f.payments.map(p=>{const m=f.matches.find(m=>m.payment_id===p.id);const opening=JSON.parse(p.data||'{}').basis==='legacy_paid_opening';return `<tr><td>${when(p.created_at)}<small>${esc(p.id.slice(0,8))}</small></td><td>${brl(p.principal)}</td><td>${brl(p.cash)}</td><td>${opening?'Baixa de abertura · conciliação pendente':p.reversed?'Estornada':m?`Conciliada · ${esc(m.statement_line)} ${button('Desfazer conciliação','finance.unreconcile',m.id)}`:button('Estornar baixa','finance.reverse',p.id)}</td></tr>`;}).join('')||empty(4,'Sem baixas registradas.')));
}

function manualFinancePanel(){
  const occurrences=[['once','Única'],['installments','Parcelada'],['weekly','Semanal'],['fortnightly','Quinzenal (15 dias)'],['monthly','Mensal'],['bimonthly','Bimestral'],['quarterly','Trimestral'],['semiannual','Semestral'],['annual','Anual']];
  return panel('Incluir conta','Cadastre despesas ou receitas independentes de uma compra ou venda. Salvar cria a conta; a baixa continua sendo uma ação separada.',`<form id="entry-form"><div class="forms"><label>Tipo<select name="kind"><option value="payable" ${financeLedgerKind==='receivable'?'':'selected'}>Conta a pagar</option><option value="receivable" ${financeLedgerKind==='receivable'?'selected':''}>Conta a receber</option></select></label><label>Cliente / Fornecedor<input name="party" required maxlength="120"></label>${moneyField('amount','Valor (R$)','')}<label>Emissão<input name="issued_on" type="date" value="${localDay()}" required></label><label>Competência<input name="competence_on" type="date" value="${localDay()}" required></label><label>Vencimento<input name="due_date" type="date" required></label></div><label>Histórico<textarea name="history" maxlength="2000" rows="3"></textarea></label><div class="reference-tabs"><button type="button" data-entry-tab="payment" class="active">Pagamento</button><button type="button" data-entry-tab="occurrence">Ocorrência</button></div><div data-entry-pane="payment"><div class="forms"><label>Forma de pagamento<input name="payment_method" maxlength="120" placeholder="Não informada"></label><label>Categoria<input name="category" maxlength="120" placeholder="Sem categoria"></label><label>N° documento<input name="document_number" maxlength="120"></label><label>Conta financeira<select name="bank_id"><option value="">Não informada</option>${(state.finance?.banks||[]).map(b=>`<option value="${esc(b.id)}">${esc(b.name||b.id)}</option>`).join('')}</select></label><label>Linha digitável do código de barras<input name="barcode" maxlength="60" inputmode="numeric" placeholder="Boleto, opcional"></label><label>Código de recolhimento<input name="tax_code" maxlength="40" placeholder="Guia, opcional"></label><label>Período de apuração<input name="tax_period" maxlength="40" placeholder="Ex.: 10/2026"></label></div></div><div data-entry-pane="occurrence" hidden><div class="forms"><label>Ocorrência<select name="occurrence">${occurrences.map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select></label><label>Número de ocorrências<input name="count" type="number" min="1" max="120" step="1" value="1" required></label></div><p class="source-line">Parcelada divide o valor total em parcelas. As demais repetições geram o valor informado em cada ocorrência. O plano completo é criado ao salvar, com até 120 ocorrências. Não ajusta feriados ou dias úteis.</p></div><div class="forms"><label>Referência única<input name="reference" value="CONTA-${crypto.randomUUID()}" required maxlength="120"></label></div><div class="form-footer"><span>Confira o plano antes de registrar as baixas. Não realiza pagamento nem cobrança bancária.</span><button>Salvar conta</button></div></form>`);
}

